# Let me read the binary directly and look for patterns
# UPX stores the compressed data and original size information

target = "{TARGET}"
with open(target, 'rb') as f:
    data = f.read()

# Find UPX! magic markers
upx_positions = []
for i in range(len(data) - 4):
    if data[i:i+4] == b'UPX!':
        upx_positions.append(i)

print("UPX! markers at:", [hex(p) for p in upx_positions])

# Look for embedded data after UPX header
# Let's check the size and structure
print(f"\nTotal file size: {len(data)} bytes")

# Look for null-terminated strings related to input/flag
interesting = []
for i in range(len(data) - 10):
    s = data[i:i+100]
    try:
        decoded = s.decode('ascii')
        if 'flag' in decoded.lower() or 'input' in decoded.lower() or 'key' in decoded.lower() or 'password' in decoded.lower():
            end = decoded.find('\x00')
            if end > 0:
                interesting.append((hex(i), decoded[:end]))
    except:
        pass

print("\nInteresting strings:")
for pos, s in interesting[:20]:
    print(f"  {pos}: {s[:60]}")

# Let's look for WebAssembly signature (0061736d = \0asm) and extract wasm
target = "{TARGET}"
with open(target, 'rb') as f:
    data = f.read()

# Look for wasm magic: 0x00 0x61 0x73 0x6d (little endian: "\0asm")
wasm_magic = b'\x00asm'
positions = []
for i in range(len(data) - 4):
    if data[i:i+4] == wasm_magic:
        positions.append(i)

print(f"WASM magic found at: {[hex(p) for p in positions]}")

# Also search for the 4-byte version that often follows
wasm_magic2 = b'\x00\x61\x73\x6d'
for i in range(len(data) - 4):
    if data[i:i+4] == wasm_magic2:
        if i not in positions:
            positions.append(i)
            print(f"Also found wasm signature at {hex(i)}")

# Let's look at the embedded data more carefully - the binary mentions "_wasm"
print("\n\nSearching for _wasm or chall_wasm patterns:")
for match in [b'_wasm', b'chall', b'wasm']:
    for i in range(len(data) - len(match)):
        if data[i:i+len(match)] == match:
            print(f"  '{match}' at {hex(i)}: context = {data[max(0,i-5):i+len(match)+20]}")

